import{_ as i,a0 as l,w as m,s as o,I as p,x as n,a1 as t,A as r,ao as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const N=JSON.parse('{"title":"Linux有问必答：如何在Linux下重命名多个文件 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有问必答：如何在Linux下重命名多个文件 | LCTT (201502) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有问必答：如何在Linux下重命名多个文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有问必答：如何在Linux下重命名多个文件 | LCTT (201502) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201502/20141224 Linux FAQs with Answers--How to rename multiple files on Linux","title":"Linux有问必答：如何在Linux下重命名多个文件","tag":"201502","desc":""},"relativePath":"201502/20141224 Linux FAQs with Answers--How to rename multiple files on Linux.md","filePath":"[post].md"}'),d={name:"201502/20141224 Linux FAQs with Answers--How to rename multiple files on Linux.md"};function g(u,e,x,j,_,f){const a=l("Link");return m(),o("div",null,[e[14]||(e[14]=p("h1",{id:"linux有问必答-如何在linux下重命名多个文件",tabindex:"-1"},[n("Linux有问必答：如何在Linux下重命名多个文件 "),p("a",{class:"header-anchor",href:"#linux有问必答-如何在linux下重命名多个文件","aria-label":"Permalink to “Linux有问必答：如何在Linux下重命名多个文件”"},"​")],-1)),e[15]||(e[15]=p("blockquote",null,[p("p",null,[p("strong",null,"提问"),n("：我知道我可以用mv命令重命名文件。但是当我想重命名很多文件怎么办？如果为每个文件都这么做将会是很乏味的。有没有办法一次性重命名多个文件？")])],-1)),p("p",null,[e[1]||(e[1]=n("在Linux中，当你想要改变一个文件名，使用mv命令就好了。然而mv不能使用通配符重命名多个文件。可以用sed、awk或者与",-1)),t(a,{href:"http://xmodulo.com/xargs-command-linux.html"},{default:r(()=>[...e[0]||(e[0]=[n("xargs",-1)])]),_:1}),e[2]||(e[2]=n("结合使用来处理多个文件的情况。然而，这些命令行即繁琐又不友好，并且如果不小心的话还很容易出错。你不会想要撤销1000个文件的错误名吧！",-1))]),e[16]||(e[16]=s(`<p>当你想要重命名多个文件的时候，rename 工具或许是最简单、最安全和最强大的命令行工具。这个rename命令实际上是一个Perl脚本，它预安装在所有的现在Linux发行版上。</p><p>下面是重命名命令的基本语法。</p><pre><code>rename [-v -n -f] &lt;pcre&gt; &lt;files&gt;
</code></pre><p>&lt;pcre&gt; 是Perl兼容正则表达式，它表示的是要重命名的文件和该怎么做。正则表达式的形式是‘s/old-name/new-name/’。</p><p>‘-v’选项会显示文件名改变的细节（比如：XXX重命名成YYY）。</p><p>‘-n’选项告诉rename命令在不实际改变名称的情况下显示文件将会重命名的情况。这个选项在你想要在不改变文件名的情况下模拟改变文件名的情况下很有用。</p><p>‘-f’选项强制覆盖存在的文件。</p><p>下面，就让我们看下rename命令的几个实际例子。</p><h3 id="改变文件扩展名" tabindex="-1">改变文件扩展名 <a class="header-anchor" href="#改变文件扩展名" aria-label="Permalink to “改变文件扩展名”">​</a></h3><p>假设你有许多.jpeg的图片文件。你想要把它们的名字改成<em>.jpg。下面的命令就会将</em>.jpeg 文件改成 *.jpg。</p><pre><code>$ rename &#39;s/\\.jpeg$/\\.jpg/&#39; *.jpeg 
</code></pre><h3 id="大写改成小写-反之亦然" tabindex="-1">大写改成小写，反之亦然 <a class="header-anchor" href="#大写改成小写-反之亦然" aria-label="Permalink to “大写改成小写，反之亦然”">​</a></h3><p>有时你想要改变文件名的大小写，你可以使用下面的命令。</p><p>把所有的文件改成小写：</p><pre><code># rename &#39;y/A-Z/a-z/&#39; *
</code></pre><p>把所有的文件改成大写：</p><pre><code># rename &#39;y/a-z/A-Z/&#39; * 
</code></pre><p><img src="https://farm9.staticflickr.com/8655/16054304245_bcf9d23b59_b.jpg" alt=""></p><h3 id="更改文件名模式" tabindex="-1">更改文件名模式 <a class="header-anchor" href="#更改文件名模式" aria-label="Permalink to “更改文件名模式”">​</a></h3><p>现在让我们考虑更复杂的包含子模式的正则表达式。在PCRE中，子模式包含在圆括号中，$符后接上数字（比如$1，$2）。</p><p>比如，下面的命令会将‘img_NNNN.jpeg’变成‘dan_NNNN.jpg’。</p><pre><code># rename -v &#39;s/img_(\\d{4})\\.jpeg$/dan_$1\\.jpg/&#39; *.jpeg
</code></pre><hr><pre><code>img_5417.jpeg renamed as dan_5417.jpg
img_5418.jpeg renamed as dan_5418.jpg
img_5419.jpeg renamed as dan_5419.jpg
img_5420.jpeg renamed as dan_5420.jpg
img_5421.jpeg renamed as dan_5421.jpg
</code></pre><p>比如，下面的命令会将‘img_000NNNN.jpeg’变成‘dan_NNNN.jpg’。</p><pre><code># rename -v &#39;s/img_\\d{3}(\\d{4})\\.jpeg$/dan_$1\\.jpg/&#39; *jpeg
</code></pre><hr><pre><code>img_0005417.jpeg renamed as dan_5417.jpg
img_0005418.jpeg renamed as dan_5418.jpg
img_0005419.jpeg renamed as dan_5419.jpg
img_0005420.jpeg renamed as dan_5420.jpg
img_0005421.jpeg renamed as dan_5421.jpg
</code></pre><p>上面的例子中，子模式‘\\d{4}’会捕捉4个连续的数字，捕捉的四个数字就是$1, 将会用于新的文件名。</p><hr>`,30)),p("p",null,[e[4]||(e[4]=n("via: ",-1)),t(a,{href:"http://ask.xmodulo.com/rename-multiple-files-linux.html"},{default:r(()=>[...e[3]||(e[3]=[n("http://ask.xmodulo.com/rename-multiple-files-linux.html",-1)])]),_:1})]),p("p",null,[e[7]||(e[7]=n("译者：",-1)),t(a,{href:"https://github.com/geekpi"},{default:r(()=>[...e[5]||(e[5]=[n("geekpi",-1)])]),_:1}),e[8]||(e[8]=n(" 校对：",-1)),t(a,{href:"https://github.com/wxy"},{default:r(()=>[...e[6]||(e[6]=[n("wxy",-1)])]),_:1})]),p("p",null,[e[11]||(e[11]=n("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[9]||(e[9]=[n("LCTT",-1)])]),_:1}),e[12]||(e[12]=n(" 原创翻译，",-1)),t(a,{href:"http://linux.cn/"},{default:r(()=>[...e[10]||(e[10]=[n("Linux中国",-1)])]),_:1}),e[13]||(e[13]=n(" 荣誉推出",-1))])])}const h=i(d,[["render",g]]);export{N as __pageData,h as default};
